#!/usr/bin/env python3
import argparse
import os
import re
import sys
from pathlib import Path


def iter_files(paths, recursive=False):
    for p in paths:
        path = Path(p)
        if path.is_file():
            yield path
        elif path.is_dir() and recursive:
            for root, _, files in os.walk(path):
                for name in files:
                    yield Path(root) / name
        elif path.is_dir():
            for child in path.iterdir():
                if child.is_file():
                    yield child


def search_file(path, pattern, ignore_case=False, line_numbers=False):
    flags = re.IGNORECASE if ignore_case else 0
    regex = re.compile(pattern, flags)

    try:
        with path.open("r", encoding="utf-8", errors="replace") as f:
            for idx, line in enumerate(f, start=1):
                if regex.search(line):
                    if line_numbers:
                        print(f"{path}:{idx}:{line.rstrip()}")
                    else:
                        print(f"{path}:{line.rstrip()}")
    except (OSError, UnicodeError):
        pass


def main():
    parser = argparse.ArgumentParser(description="grep-like tool in Python")
    parser.add_argument("pattern", help="Regex pattern to search for")
    parser.add_argument("paths", nargs="+", help="Files or directories to search")
    parser.add_argument("-r", "--recursive", action="store_true", help="Recurse into directories")
    parser.add_argument("-i", "--ignore-case", action="store_true", help="Case-insensitive matching")
    parser.add_argument("-n", "--line-number", action="store_true", help="Show line numbers")
